base.r/main.tf:
terraform {
  backend "s3" {}
}
resource "aws_iam_policy" "p" {
  name   = "deployer"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{"Sid": "DeployAll", "Effect": "Allow", "Action": "s3:*", "Resource": "arn:aws:s3:::*"}]
  })
}

